// Writes data/Guide.lua for the addon from plans/guide-rxp.js:  node dev/elle-config/emit-guide.js
const fs = require('fs');
const path = require('path');
const L = require('./src/luatable.js');

// plain JS value -> the Map trees luatable writes (arrays become tables with keys 1..n)
function tree(v) {
  if (Array.isArray(v)) return new Map(v.map((x, i) => [i + 1, tree(x)]));
  if (v && typeof v === 'object') return new Map(Object.entries(v).map(([k, x]) => [k, tree(x)]));
  return v;
}
function emit(plan) {
  const lines = [
    '-- GENERATED by dev/elle-config/emit-guide.js from dev/elle-config/plans/guide-rxp.js. Do not edit by hand.',
    '-- RestedXP Guides settings, applied by /qb layout apply (modules/Loadout.lua).',
    'local _, QB = ...',
    'QB.guideData = {',
    '  v = 1,',
    '  name = ' + L.lua(plan.name) + ',',
    '  sets = {',
  ];
  let n = 0;
  for (const [k, v] of Object.entries(plan.values)) {
    // a table of sub-tables (framePositions) is written one entry at a time, so other entries in it are left alone
    const entries = v && typeof v === 'object' && !Array.isArray(v) ? Object.entries(v).map(([k2, v2]) => [[k, k2], v2]) : [[[k], v]];
    for (const [p, val] of entries) {
      lines.push('    { path = { "profiles", "$profile", ' + p.map((x) => L.lua(x)).join(', ') + ' }, value = ' + L.lua(tree(val)).replace(/\n/g, ' ') + ' },');
      n++;
    }
  }
  lines.push('  },', '  removes = {', '  },', '}', '');
  return { text: lines.join('\n'), sets: n };
}
module.exports = { emit };
if (require.main === module) {
  const r = emit(require('./plans/guide-rxp.js'));
  fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'Guide.lua'), r.text);
  console.log('wrote data/Guide.lua:', r.sets, 'values');
}
